export function resolveName(name, nodes, aliases) {
  let target = name;
  const seen = new Set();
  while (Object.prototype.hasOwnProperty.call(aliases, target)) {
    if (seen.has(target)) throw new Error('Alias cycle: ' + target);
    seen.add(target);
    target = aliases[target];
  }
  if (!Object.prototype.hasOwnProperty.call(nodes, target)) throw new Error('Unknown node: ' + target);
  return target;
}

